/* ========================================
   RedRoom Fitness — Global Styles
   ======================================== */

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg: #141414;
  --bg-elevated: #1a1a1a;
  --bg-card: #1e1e1e;
  --red: #FF0000;
  --red-dark: #cc0000;
  --red-glow: rgba(255, 0, 0, 0.35);
  --text: #FFFFFF;
  --text-muted: #a0a0a0;
  --text-dim: #666666;
  --border: #2a2a2a;
  --border-light: #333333;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --radius: 0.5rem;
  --transition: 200ms ease-out;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.4);
  --shadow: 0 4px 12px rgba(0,0,0,0.5);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ========================================
   Typography
   ======================================== */

.display {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.05;
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
}

.text-red { color: var(--red); }
.text-muted { color: var(--text-muted); }

/* ========================================
   Layout Utilities
   ======================================== */

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

@media (min-width: 768px) {
  .container { padding: 0 2rem; }
}

@media (min-width: 1024px) {
  .container { padding: 0 2.5rem; }
}

.section {
  padding: 4rem 0;
}

@media (min-width: 768px) {
  .section { padding: 5rem 0; }
}

@media (min-width: 1024px) {
  .section { padding: 6rem 0; }
}

/* ========================================
   Buttons
   ======================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-radius: var(--radius);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 4px 20px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--text);
}

.btn-outline:hover {
  background: var(--text);
  color: var(--bg);
  transform: translateY(-2px);
}

.btn-ghost {
  background: transparent;
  color: var(--text);
  border-color: transparent;
}

.btn-ghost:hover {
  color: var(--red);
}

.btn-lg {
  padding: 1rem 2.5rem;
  font-size: 1.1rem;
}

/* ========================================
   Navigation
   ======================================== */

.top-bar {
  background: var(--red);
  color: #fff;
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.8rem;
  font-weight: 500;
}

.top-bar a {
  text-decoration: underline;
  margin-left: 0.5rem;
}

.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(20, 20, 20, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text);
}

.logo span {
  color: var(--red);
}

.nav-links {
  display: none;
  gap: 1.75rem;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  transition: color var(--transition);
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-utility {
  display: none;
  gap: 1rem;
  align-items: center;
}

.nav-utility a {
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  transition: color var(--transition);
}

.nav-utility a:hover {
  color: var(--red);
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: none;
  border: none;
  color: var(--text);
  cursor: pointer;
}

.mobile-nav {
  display: none;
  position: absolute;
  top: 64px;
  left: 0;
  right: 0;
  background: var(--bg-elevated);
  border-bottom: 1px solid var(--border);
  padding: 1.5rem;
}

.mobile-nav.open {
  display: block;
}

.mobile-nav a {
  display: block;
  padding: 0.75rem 0;
  font-family: var(--font-display);
  font-size: 1rem;
  text-transform: uppercase;
  border-bottom: 1px solid var(--border);
  color: var(--text-muted);
}

.mobile-nav a:hover,
.mobile-nav a.active {
  color: var(--text);
}

@media (min-width: 1024px) {
  .nav-links { display: flex; }
  .nav-utility { display: flex; }
  .mobile-menu-btn { display: none; }
}

/* ========================================
   Hero
   ======================================== */

.hero {
  position: relative;
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.35);
  z-index: 0;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(20,20,20,0.3) 0%, rgba(20,20,20,0.8) 100%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 2rem 1.5rem;
}

.hero-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  margin-bottom: 1rem;
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--text-muted);
  margin-bottom: 2rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* ========================================
   Cards
   ======================================== */

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: all var(--transition);
}

.card:hover {
  border-color: var(--border-light);
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

/* ========================================
   Footer
   ======================================== */

.footer {
  background: var(--bg-elevated);
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.footer-col h4 {
  font-size: 0.85rem;
  margin-bottom: 1rem;
  color: var(--text);
}

.footer-col a {
  display: block;
  font-size: 0.85rem;
  color: var(--text-muted);
  padding: 0.25rem 0;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--red);
}

.footer-bottom {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
}

.country-select {
  position: relative;
}

.country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  right: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.5rem 0;
  min-width: 160px;
  margin-bottom: 0.5rem;
  box-shadow: var(--shadow);
}

.country-dropdown.open {
  display: block;
}

.country-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.5rem 1rem;
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.85rem;
  cursor: pointer;
  transition: color var(--transition);
}

.country-dropdown button:hover {
  color: var(--text);
  background: var(--bg-elevated);
}

/* ========================================
   Forms
   ======================================== */

.form-input {
  width: 100%;
  padding: 0.875rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-size: 0.95rem;
  transition: border-color var(--transition);
}

.form-input:focus {
  outline: none;
  border-color: var(--red);
}

.form-input::placeholder {
  color: var(--text-dim);
}

.form-error {
  color: #ff5555;
  font-size: 0.8rem;
  margin-top: 0.5rem;
}

.form-success {
  color: #4ade80;
  font-size: 0.9rem;
  margin-top: 0.5rem;
}

/* ========================================
   Carousel
   ======================================== */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 400ms ease-out;
}

.carousel-slide {
  min-width: 100%;
  flex-shrink: 0;
}

.carousel-slide img {
  width: 100%;
  height: 400px;
  object-fit: cover;
}

@media (min-width: 768px) {
  .carousel-slide img { height: 500px; }
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(20,20,20,0.7);
  backdrop-filter: blur(4px);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  z-index: 10;
}

.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel-btn.prev { left: 1rem; }
.carousel-btn.next { right: 1rem; }

.carousel-dots {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  margin-top: 1rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border-light);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--red);
  width: 24px;
  border-radius: 4px;
}

/* ========================================
   Toggle
   ======================================== */

.toggle-group {
  display: inline-flex;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.toggle-btn {
  padding: 0.75rem 1.5rem;
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}

.toggle-btn.active {
  background: var(--red);
  color: #fff;
}

.toggle-content {
  display: none;
}

.toggle-content.active {
  display: block;
  animation: fadeIn 300ms ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ========================================
   Accordion
   ======================================== */

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  background: none;
  border: none;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
}

.accordion-header:hover {
  color: var(--red);
}

.accordion-icon {
  transition: transform 300ms ease-out;
  flex-shrink: 0;
}

.accordion-item.open .accordion-icon {
  transform: rotate(180deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease-out, padding 300ms ease-out;
}

.accordion-item.open .accordion-body {
  max-height: 300px;
  padding-bottom: 1.25rem;
}

.accordion-body p {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ========================================
   Filter
   ======================================== */

.filter-bar {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.filter-btn {
  padding: 0.5rem 1.25rem;
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 2rem;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}

.filter-btn:hover,
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}

/* ========================================
   Instructor Card
   ======================================== */

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: var(--border-light);
  transform: translateY(-4px);
  box-shadow: var(--shadow);
}

.instructor-card .card-img {
  width: 100%;
  height: 260px;
  object-fit: cover;
  filter: grayscale(0.3);
  transition: filter var(--transition);
}

.instructor-card:hover .card-img {
  filter: grayscale(0);
}

.instructor-card .card-body {
  padding: 1.25rem;
}

.instructor-card h3 {
  font-size: 1.1rem;
  margin-bottom: 0.25rem;
}

.instructor-card .location {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.instructor-card .card-link {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  color: var(--red);
  transition: color var(--transition);
}

.instructor-card .card-link:hover {
  color: var(--text);
}

/* ========================================
   Table
   ======================================== */

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th,
.data-table td {
  padding: 1rem 1.25rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}

.data-table th {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  background: var(--bg-elevated);
}

.data-table td {
  font-size: 0.95rem;
  color: var(--text);
}

.data-table tr:hover td {
  background: var(--bg-elevated);
}

/* ========================================
   Feature Blocks
   ======================================== */

.feature-block {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
}

.feature-icon {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  background: rgba(255,0,0,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--red);
}

.feature-block h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.feature-block p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* ========================================
   Animations
   ======================================== */

@keyframes slideUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: slideUp 600ms ease-out forwards;
}

/* ========================================
   Utility
   ======================================== */

.grid-2 {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
}

.grid-3 {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
}

.grid-4 {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
}

.text-center { text-align: center; }

.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }
.mb-5 { margin-bottom: 3rem; }

.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }

.gap-2 { gap: 1rem; }
.gap-3 { gap: 1.5rem; }
